python3 << 'EOF'
import json, re

def close(a, b, tol=0.5): return abs(a-b) <= tol
errs = []

# 1. Exact back-solve: 0.18*(P-1,500,000)/P = 0.061
P = 270000/0.119
if not close(P, 2268908, tol=0.6): errs.append(f"P {P:.2f}")
if not close(P-1500000, 768908, tol=0.6): errs.append(f"pre-money {P-1500000:.2f}")

# 2. New §3(3) figures
if not close(0.061*7200000, 439200): errs.append("439,200")
honest = 0.18*7.2/8.7
if not close(0.1425*7200000, 1026000): errs.append("1,026,000")
if not close(honest*7200000, 1072552, tol=0.6): errs.append(f"1,072,552 -> {honest*7200000:.2f}")
if not close(honest*9800000, 1459862, tol=0.5): errs.append("1,459,862")
if not close(1-189100/439200, 0.57, tol=0.005): errs.append(f"57% -> {1-189100/439200:.4f}")

# 3. Core reconciliation set (unchanged numbers)
core = {
 "0.061x3.1M": (0.061*3100000, 189100), "0.061x9.8M": (0.061*9800000, 597800),
 "0.18x9.8M": (0.18*9800000, 1764000), "0.119x9.8M": (0.119*9800000, 1166200),
 "1764000-597800": (1764000-597800, 1166200), "0.1425x9.8M": (0.1425*9800000, 1396500),
 "fees total": (180000+195000+210000+225000+240000, 1050000),
 "in-window": (210000+225000+240000, 675000), "barred": (180000+195000, 375000),
 "18% x 675k": (0.18*675000, 121500), "18% x 1050k": (0.18*1050000, 189000),
 "18% x 3.1M": (0.18*3100000, 558000), "offer ratio 10.7%": (189100/1764000, 0.1071),
 "offer ratio 31.6%": (189100/597800, 0.3163), "3.16x": (9800000/3100000, 3.161),
 "+36%": (9.8/7.2-1, 0.3611), "escalations": ((195-180)/180, 0.0833),
}
for k,(c,s) in core.items():
    tol = 0.5 if abs(s) > 1000 else 0.0006
    if not close(c, s, tol): errs.append(f"{k}: {c} vs {s}")
print("ARITHMETIC:", "ALL OK" if not errs else errs)

# 4. Cutoff logic
for p in ["2022-09-01", "2023-09-01"]:
    print(f"{p}: before 2023-10-25? {p < '2023-10-25'} | before 2023-10-08? {p < '2023-10-08'}")

# 5. JSON validity
files = ["claims.json", "valuation_gap.json", "strategy_memo.md", "QUESTIONS.md", "STATUS.md"]
for f in files[:2]:
    d = json.load(open(f"/work/workspace/deliverable/{f}"))
    print(f"{f}: valid JSON, entries={len(d)}")

# 6. Stale-token scan
stale = re.compile(r"2,268,877|768,877|456,700|2023-10-08")
hits = 0
for f in files:
    for i, ln in enumerate(open(f"/work/workspace/deliverable/{f}"), 1):
        for m in stale.finditer(ln):
            hits += 1; print(f"STALE {f}:{i}: {m.group()} ctx ...{ln[max(0,m.start()-50):m.end()+50].strip()}...")
print("stale tokens:", hits)

# 7. [unverified] discipline + date-ref counts
for f in files:
    txt = open(f"/work/workspace/deliverable/{f}").read()
    print(f"{f}: unverified-flags={txt.count('[unverified')}  2026-10-25={txt.count('2026-10-25')}  2026-10-08={txt.count('2026-10-08')}")

# 8. Render check, edited memo regions
memo = open("/work/workspace/deliverable/strategy_memo.md").read().splitlines()
for i in [2, 9, 25, 27, 45, 47, 48, 63, 77, 91]:
    print(f"\nmemo {i+1}: {memo[i][:430]}")
EOF

